package com.ventas.controller;
import com.ventas.dto.ReportModels.*;import com.ventas.service.ReportService;import com.ventas.security.AuthModels.Identity;import java.time.*;import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.context.annotation.Profile;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;
@RestController @Profile("db") @RequestMapping("/api/reportes") public class ReportController{
 private final ReportService service;public ReportController(ReportService service){this.service=service;}
 @GetMapping("/fechas") public Dates dates(@AuthenticationPrincipal Identity a){return service.dates(a);}
 @GetMapping("/productos/opciones") public List<Map<String,Object>> products(@AuthenticationPrincipal Identity a,@RequestParam(defaultValue="") String buscar,@RequestParam(defaultValue="0") int pagina){return service.products(a,buscar,pagina);}
 @GetMapping("/{tipo}") public Object report(@AuthenticationPrincipal Identity a,@PathVariable String tipo,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate desde,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate hasta,@RequestParam(required=false) Long producto,@RequestParam(defaultValue="") String buscar,@RequestParam(defaultValue="0") int pagina){var f=new Filter(desde,hasta,producto,buscar,pagina);return switch(tipo){case "inventario"->service.inventory(a,f);case "caja"->service.cash(a,f);default->service.sales(a,tipo,f);};}
 @GetMapping("/{tipo}/csv") public ResponseEntity<byte[]> csv(@AuthenticationPrincipal Identity a,@PathVariable String tipo,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate desde,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate hasta,@RequestParam(required=false) Long producto,@RequestParam(defaultValue="") String buscar,HttpServletRequest request){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=reporte-"+tipo+"-"+desde+"-"+hasta+".csv").contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).body(service.export(a,request.getRemoteAddr(),tipo,new Filter(desde,hasta,producto,buscar,0)));}
}
